"""AI attribution: this whole file was generated by Claude (Anthropic) in Claude Code, following
design decisions made by the author. See ATTRIBUTION.md for details.

P1 v0.4 features at every decision point (plan 3.1, 5.5, 6.1): transcripts, speaker embeddings, detected sounds.

Audio: the full mix of every version of a unit is rebuilt from its meta row with the renderer's own mixer
(p1v4_units.render_versions; the TTS cache makes this fast); episodes are read from their stored full mix. Every
stored 8 s window must equal the rebuilt audio within +-1 LSB (the renderer's own identity tolerance; the GPU venv's
numpy 2.5.4 against the render venv's 2.5.1 can round a sample differently), otherwise the script stops; units with
a 1-LSB difference are listed in the check file.

At decision point k (time t):
- Speech segments (plan 3.1: every speech segment cut at its scripted times): each speech or TV source that starts
  before t. A finished one (end <= t) is cut from its start to min(end + 0.2 s, t) and keyed by its id (the line just
  said ends 0.2 s before t, so it is cut to t, as v0.3 cut the line); one still going at t is cut to t and keyed
  "<id>@<k>" (p1v4_situation.build reads both keys). Identical cuts (same samples) are processed once, keyed by sha1.
- Transcripts: Whisper-small (openai/whisper-small rev 973afd2), fp16, greedy, English, the cut padded to 30 s.
- Speaker embeddings: ECAPA-TDNN (speechbrain/spkrec-ecapa-voxceleb rev 0f99f2d, step 0 item 3). Enrolment: the
  unit's user voice reading a fixed passage of about 10 s (ENROL_TEXT), clean TTS, once per voice. The user / not the
  user threshold on the cosine is chosen on dev afterwards (p1v4_context.py), shared by all systems.
- Detected sounds: the shared detector (p1v4_sed.py, chosen epoch) run on the audio from the unit start to t (only
  audio before t); per class, runs of frames with probability >= 0.2, runs closer than 0.3 s merged: (class, start,
  end, peak), times in unit seconds.

Outputs per render folder (dev, train_d00 ... train_d11), data/p1v4/feats/<folder>_*: segs.json (point id -> {key:
sha1}), text_small.json (sha1 -> transcript), spk_emb.npy + spk_ids.json (sha1 -> 192-d embedding), enrol.json (voice
-> embedding), sounds.json (point id -> [[class, start, end, peak]]), check.json (windows compared). Point id =
"unit|version|k".

usage: python -X utf8 scripts/p1v4_feats.py enrol-tts train|dev             (project venv with Kokoro: enrolment TTS)
       python -X utf8 scripts/p1v4_feats.py enrol-tts-voices dev|test|replication
              (project venv; added 2026-11-21, freeze amendment 13.2: the enrolment passage of every voice the split's
               generator can draw, built from results/step0/aux_splits.json without reading any row; on dev the
               format is checked against the rows' cached voices; run() stops early if a voice is not cached)
       python -X utf8 scripts/p1v4_feats.py run <folder> <detector.pt>      (GPU venv; folder = dev, train_d00, ...)
"""
import copy
import hashlib
import json
import os
import sys
import time
from types import SimpleNamespace

import numpy as np
import soundfile as sf

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import p1v4_data as D  # noqa: E402

SR = 16000
OUT = "data/p1v4/feats"
ENROL_TEXT = ("When the sunlight strikes raindrops in the air, they act as a prism and form a rainbow. "
              "The rainbow is a division of white light into many beautiful colors.")
WHISPER = ("openai/whisper-small", "973afd24965f72e36ca33b3055d56a652f456b4d")
ECAPA_SRC = "data/models_dl/spkrec-ecapa-voxceleb_0f99f2d"
ECAPA_DST = "data/models_dl/spkrec-ecapa-voxceleb"
SOUND_THR, MERGE_GAP_S = 0.2, 0.3
LINE_TAIL_S = 0.2
MAX_DIFF_LSB = 1


def voice_key(v):
    return json.dumps(v, sort_keys=True)


def enrol_audio(voice):
    import p1v4_units as U
    return U.say(ENROL_TEXT, voice)


def enrol_tts(which):
    rows = D.load_rows(which)
    voices = {voice_key(r["spec"]["user"]): r["spec"]["user"] for r in rows}
    for k, v in sorted(voices.items()):
        x = enrol_audio(v)
        print(f"{k}: {len(x) / SR:.1f} s", flush=True)


def enrol_cache_path(voice):
    """The TTS cache file of a voice's enrolment passage: p1_render.tts's key (engine|voice|speaker|text)."""
    import p1_render as R
    key = hashlib.sha1(f"{voice.get('engine', 'kokoro')}|{voice.get('voice')}|{voice.get('speaker')}|{ENROL_TEXT}"
                       .encode("utf-8")).hexdigest()[:16]
    return os.path.join(R.TTS_CACHE, key + ".npy").replace("\\", "/")


def aux_voices(split):
    """Every user-voice spec a split's generator can draw (p1v4_units.Assets and base(): the Kokoro voices of the split,
    test's for replication, and the split's Piper speakers), built from results/step0/aux_splits.json only: no row of
    the split is read (freeze amendment 13.2, pre-test code review B1). Same dict format as the rows' spec["user"]."""
    aux = json.load(open("results/step0/aux_splits.json", encoding="utf-8"))
    a = "test" if split == "replication" else split
    out = [{"engine": "kokoro", "voice": v} for v in aux["voices"][a]]
    out += [{"engine": "piper", "voice": "piper", "speaker": int(s)} for s in aux["piper_speakers"].get(split, [])]
    return out


def enrol_tts_voices(split):
    """The enrolment passage of every voice in aux_voices(split), synthesised into the TTS cache (project venv: Kokoro
    and Piper). On dev and train first the format check: every user voice of the split's rows must be one of the
    voices built from the step-0 file, and its cache file must already exist. Writes
    results/main_v04/enrol_voices_<split>.json (voices, cache files, sha256, whether newly made)."""
    voices = aux_voices(split)
    keys = {voice_key(v) for v in voices}
    check = None
    if split in ("dev", "train"):
        rows = D.load_rows(split)
        used = {voice_key(r["spec"]["user"]): r["spec"]["user"] for r in rows}
        check = {"row_voices": len(used), "built_from_step0": len(voices),
                 "row_voices_not_built": sorted(k for k in used if k not in keys),
                 "row_voices_cached": sum(os.path.exists(enrol_cache_path(v)) for v in used.values())}
        print(json.dumps(check), flush=True)
        if check["row_voices_not_built"] or check["row_voices_cached"] != len(used):
            raise SystemExit("the voices built from aux_splits.json do not reproduce the rows' cached voices")
    out = []
    for v in voices:
        p = enrol_cache_path(v)
        had = os.path.exists(p)
        x = enrol_audio(v)
        if not os.path.exists(p):
            raise SystemExit(f"{p} was not written for {v}")
        out.append({"voice": v, "path": p, "new": not had, "seconds": round(len(x) / SR, 2),
                    "sha256": hashlib.sha256(open(p, "rb").read()).hexdigest()})
        print(f"{voice_key(v)}: {len(x) / SR:.1f} s {'new' if not had else 'cached'} {p}", flush=True)
    res = {"split": split, "text": ENROL_TEXT, "check": check, "voices": out,
           "time": time.strftime("%Y-%m-%d %H:%M:%S")}
    json.dump(res, open(f"results/main_v04/enrol_voices_{split}.json", "w"), indent=1)
    print(f"{split}: {len(out)} voices, {sum(o['new'] for o in out)} newly synthesised", flush=True)


def check_enrol_cached(rows, which):
    """Stop before any work when a user voice of the folder has no cached enrolment passage (the GPU venv has no TTS;
    pre-test code review B1)."""
    used = {voice_key(r["spec"]["user"]): r["spec"]["user"] for r in rows}
    miss = sorted(k for k, v in used.items() if not os.path.exists(enrol_cache_path(v)))
    if miss:
        split = which.split("_d")[0]
        raise SystemExit(f"{which}: {len(miss)} of {len(used)} user voices have no cached enrolment passage, e.g. "
                         f"{miss[:3]}; run `.venv/Scripts/python.exe -X utf8 scripts/p1v4_feats.py enrol-tts-voices "
                         f"{split}` (project venv) first")


# ------------------------------------------------------------------------------------------------ audio per unit

def segment_cuts(r, x):
    """[(point id, key, int16 cut)] for every speech segment that starts before each decision point."""
    out = []
    for p in r["points"]:
        t = p["t"]
        pid = f"{r['unit']}|{r['version']}|{p['k']}"
        for s in r["sources"]:
            if s["kind"] not in ("speech", "tvfile") or s["start"] >= t:
                continue
            if s["end"] > t:
                key, end = f"{s['id']}@{p['k']}", t
            else:
                key, end = s["id"], min(s["end"] + LINE_TAIL_S, t)
            a, b = int(round(s["start"] * SR)), int(round(end * SR))
            out.append((pid, key, x[a:b]))
    return out


def identity(x):
    return x


class UnitAudio:
    """Torch-style dataset: item i = one unit (all its versions): rebuilt audio, window check, cuts and prefixes."""

    def __init__(self, units, split):
        self.units, self.split, self.A = units, split, None

    def __len__(self):
        return len(self.units)

    def __getitem__(self, i):
        import p1v4_units as U
        rows = self.units[i]
        if rows[0]["part"] == "episode":
            audio = {r["version"]: sf.read(r["full"], dtype="int16")[0] for r in rows}
            gain_ok = True
        else:
            if self.A is None:
                self.A = U.Assets(self.split)
            spec = copy.deepcopy(rows[0]["spec"])
            tls = {r["version"]: SimpleNamespace(src=r["sources"], points=r["points"], assistant=r["assistant"])
                   for r in rows}
            audio, gain_db = U.render_versions(spec, tls, self.A)
            gain_ok = abs(gain_db - rows[0]["gain_db"]) < 1e-9
        n_win, max_diff = 0, 0
        cuts, prefixes = [], []
        for r in rows:
            x = audio[r["version"]]
            for p in r["points"]:
                e = int(round(p["t"] * SR))
                w = sf.read(p["window"], dtype="int16")[0]
                c = x[e - int(D.WIN_S * SR):e]
                n_win += 1
                max_diff = max(max_diff, int(np.abs(w.astype(np.int32) - c.astype(np.int32)).max())
                               if len(w) == len(c) else 1 << 20)
                prefixes.append((f"{r['unit']}|{r['version']}|{p['k']}", x[:e]))
            cuts += segment_cuts(r, x)
        return {"unit": rows[0]["unit"], "user": rows[0]["spec"]["user"], "gain_ok": gain_ok, "n_win": n_win,
                "max_diff": max_diff, "cuts": cuts, "prefixes": prefixes}


# ------------------------------------------------------------------------------------------------ models

def load_ecapa(device="cuda"):
    import torchaudio
    if not hasattr(torchaudio, "list_audio_backends"):     # torchaudio 2.11 shim (we pass arrays, no torchaudio I/O)
        torchaudio.list_audio_backends = lambda: ["soundfile"]
    from speechbrain.inference.speaker import EncoderClassifier
    from speechbrain.utils.fetching import LocalStrategy
    src, dst = os.path.abspath(ECAPA_SRC), os.path.abspath(ECAPA_DST)
    return EncoderClassifier.from_hparams(source=src, savedir=dst, overrides={"pretrained_path": src},
                                          run_opts={"device": device}, pymodule_file="",
                                          local_strategy=LocalStrategy.COPY)


class Whisper:
    def __init__(self, name, rev):
        import torch
        from transformers import WhisperFeatureExtractor, WhisperForConditionalGeneration, WhisperTokenizer
        self.torch = torch
        self.fe = WhisperFeatureExtractor.from_pretrained(name, revision=rev)
        self.tok = WhisperTokenizer.from_pretrained(name, revision=rev)
        self.model = WhisperForConditionalGeneration.from_pretrained(name, revision=rev,
                                                                     dtype=torch.float16).cuda().eval()
        self.filters = torch.tensor(self.fe.mel_filters, dtype=torch.float32, device="cuda")
        self.window = torch.hann_window(self.fe.n_fft, device="cuda")

    def __call__(self, xs):
        """xs: list of float32 arrays (<= 30 s) -> transcripts (as v0.3 scripts/p1_asr.py)."""
        torch = self.torch
        pad = np.zeros((len(xs), 30 * SR), np.float32)
        for i, x in enumerate(xs):
            x = x[-30 * SR:]
            pad[i, :len(x)] = x
        with torch.no_grad():
            x = torch.from_numpy(pad).cuda()
            st = torch.stft(x, self.fe.n_fft, self.fe.hop_length, window=self.window, return_complex=True)
            mel = self.filters.T @ (st[..., :-1].abs() ** 2)
            lg = torch.clamp(mel, min=1e-10).log10()
            lg = torch.maximum(lg, lg.amax(dim=(-2, -1), keepdim=True) - 8.0)
            feats = ((lg + 4.0) / 4.0).half()
            ids = self.model.generate(feats, language="en", task="transcribe", max_new_tokens=160, do_sample=False)
        return [t.strip() for t in self.tok.batch_decode(ids, skip_special_tokens=True)]


def sound_segments(frames, fps=100):
    """frames: (n, C) probabilities -> [[class, start, end, peak]] (runs >= SOUND_THR, gaps < MERGE_GAP_S merged)."""
    out = []
    for c, name in enumerate(D.DET_CLASSES):
        on = np.nonzero(frames[:, c] >= SOUND_THR)[0]
        if not len(on):
            continue
        runs, a, b = [], on[0], on[0]
        for i in on[1:]:
            if i - b > MERGE_GAP_S * fps:
                runs.append((a, b))
                a = i
            b = i
        runs.append((a, b))
        for a, b in runs:
            out.append([name, round(float(a) / fps, 2), round(float(b + 1) / fps, 2),
                        round(float(frames[a:b + 1, c].max()), 3)])
    return sorted(out, key=lambda s: (s[1], s[0]))


# ------------------------------------------------------------------------------------------------ main pass

def run(which, ckpt, workers=10, limit=None):
    """which: a render folder name (dev, train_d00 ... train_d11)."""
    import torch
    import p1v4_sed as SED
    if which.startswith(("test", "replication")) and not D.final_unlocked():     # opens only after the freeze
        raise SystemExit("test and replication are featurised only in the single final run (plan 8.5)")
    os.makedirs(OUT, exist_ok=True)
    rows = D.folder_rows(os.path.join(D.RENDER, which))
    check_enrol_cached(rows, which)                  # amendment 13.2: no TTS in this venv, so fail before any work
    units, order = {}, []
    for r in rows:
        if r["unit"] not in units:
            units[r["unit"]] = []
            order.append(r["unit"])
        units[r["unit"]].append(r)
    if limit:
        order = order[:limit]
    split = which.split("_d")[0]
    ds = UnitAudio([units[u] for u in order], split)
    dl = torch.utils.data.DataLoader(ds, batch_size=None, shuffle=False, num_workers=workers, prefetch_factor=4,
                                     collate_fn=identity, persistent_workers=False)
    whisper = Whisper(*WHISPER)
    ecapa = load_ecapa()
    det = SED.load(ckpt)
    enrol = {}
    segs, text, emb, sounds = {}, {}, {}, {}
    pending = {}
    check = {"units": 0, "windows": 0, "max_diff": 0, "gain_mismatch": [], "diff_units": []}

    def flush():
        keys = sorted(pending, key=lambda k: len(pending[k]))
        for i in range(0, len(keys), 32):
            ks = keys[i:i + 32]
            xs = [pending[k].astype(np.float32) / 32768.0 for k in ks]
            for k, tr in zip(ks, whisper(xs)):
                text[k] = tr
            n = max(len(x) for x in xs)
            wav = np.zeros((len(xs), n), np.float32)
            for j, x in enumerate(xs):
                wav[j, :len(x)] = x
            lens = torch.tensor([len(x) / n for x in xs], dtype=torch.float32)
            with torch.no_grad():
                e = ecapa.encode_batch(torch.from_numpy(wav).cuda(), lens.cuda()).squeeze(1).float().cpu().numpy()
            for k, v in zip(ks, e):
                emb[k] = v.astype(np.float16)
        pending.clear()

    t0 = time.time()
    for n_done, item in enumerate(dl, 1):
        check["units"] += 1
        check["windows"] += item["n_win"]
        check["max_diff"] = max(check["max_diff"], item["max_diff"])
        if not item["gain_ok"]:
            check["gain_mismatch"].append(item["unit"])
        if item["max_diff"] > 0:
            check["diff_units"].append(item["unit"])
        if check["max_diff"] > MAX_DIFF_LSB or check["gain_mismatch"]:
            json.dump(check, open(f"{OUT}/{which}_check.json", "w"), indent=1)
            raise SystemExit(f"rebuilt audio differs from the stored windows: {item['unit']}")
        vk = voice_key(item["user"])
        if vk not in enrol:
            x = enrol_audio(item["user"]).astype(np.float32)
            with torch.no_grad():
                enrol[vk] = ecapa.encode_batch(torch.from_numpy(x)[None].cuda()).squeeze().float().cpu().numpy()
        for pid, key, cut in item["cuts"]:
            h = hashlib.sha1(cut.tobytes()).hexdigest()
            segs.setdefault(pid, {})[key] = h
            if h not in text and h not in pending:
                pending[h] = cut
        if len(pending) >= 256:
            flush()
        for pid, x in item["prefixes"]:
            xx = torch.from_numpy(SED.to32(x.astype(np.float32) / 32768.0))[None].cuda()
            with torch.no_grad(), torch.autocast("cuda", dtype=torch.bfloat16):
                f, _, _ = SED.forward(det, xx)
            n_keep = int(np.floor(len(x) / SR * 100)) + 1
            sounds[pid] = sound_segments(f[0, :n_keep].float().cpu().numpy())
        if n_done % 500 == 0:
            el = time.time() - t0
            print(f"{which}: {n_done}/{len(order)} units, {len(text) + len(pending)} cuts, "
                  f"{el / 60:.1f} min, eta {el / n_done * (len(order) - n_done) / 60:.0f} min", flush=True)
    flush()
    if limit:
        print(json.dumps(check))
        return segs, text, sounds
    ids = sorted(emb)
    np.save(f"{OUT}/{which}_spk_emb.npy", np.stack([emb[k] for k in ids]))
    json.dump(ids, open(f"{OUT}/{which}_spk_ids.json", "w"))
    json.dump(segs, open(f"{OUT}/{which}_segs.json", "w"))
    json.dump(text, open(f"{OUT}/{which}_text_small.json", "w", encoding="utf-8"), ensure_ascii=False)
    json.dump({k: v.tolist() for k, v in enrol.items()}, open(f"{OUT}/{which}_enrol.json", "w"))
    json.dump(sounds, open(f"{OUT}/{which}_sounds.json", "w"))
    check["minutes"] = round((time.time() - t0) / 60, 1)
    check["unique_cuts"] = len(text)
    check["points"] = len(sounds)
    json.dump(check, open(f"{OUT}/{which}_check.json", "w"), indent=1)
    print(json.dumps(check))


if __name__ == "__main__":
    if sys.argv[1] == "enrol-tts":
        enrol_tts(sys.argv[2])
    elif sys.argv[1] == "enrol-tts-voices":
        enrol_tts_voices(sys.argv[2])
    elif sys.argv[1] == "run":
        run(sys.argv[2], sys.argv[3])
    elif sys.argv[1] == "try":                      # quick check on the first N units of a folder, nothing written
        segs, text, sounds = run(sys.argv[2], sys.argv[3], workers=2, limit=int(sys.argv[4]))
        for pid in list(segs)[:6]:
            print(pid, {k: text.get(h, "?") for k, h in segs[pid].items()}, sounds.get(pid))
    else:
        raise SystemExit(__doc__)
